# Quick empirical probe: open(path,"x") succeeds, first write raises OSError
# before delegating; confirm the file is left zero bytes and the with-block
# close adds no stderr noise.
import os, tempfile, io

class Deny:
    def __init__(self, raw): self._raw = raw
    def write(self, data): raise OSError("report-body-write-denied")
    def __enter__(self):
        self._raw.__enter__(); return self
    def __exit__(self, *exc): return self._raw.__exit__(*exc)
    def __getattr__(self, n): return getattr(self._raw, n)

d = tempfile.mkdtemp()
p = os.path.join(d, "report.json")
raw = open(p, "x", encoding="utf-8", newline="")
try:
    with Deny(raw) as fh:
        fh.write('{"a": 1}\n')
except OSError as e:
    print("caught:", e)
print("exists:", os.path.exists(p), "size:", os.path.getsize(p))
EOF
